create table if not exists invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,email text not null,role text not null,facility_id uuid references facilities(id) on delete cascade,token_hash text unique not null,status text not null default 'pending',expires_at timestamptz not null,created_by uuid references users(id),accepted_user_id uuid references users(id),accepted_at timestamptz,created_at timestamptz not null default now());
create index if not exists invitations_org_status_idx on invitations(organization_id,status,created_at desc);
create table if not exists organization_settings(organization_id uuid primary key references organizations(id) on delete cascade,settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists facility_settings(facility_id uuid primary key references facilities(id) on delete cascade,settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
